import{_ as t,o as n,c as i,a2 as a}from"./chunks/framework.vLhlLNVn.js";const r="/assets/einheit-beheben.CnWHg7pI.png",m=JSON.parse('{"title":"Log-Meldungen und Fehler beim Einrichten","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/04.fehlerbehebung/01.log-meldungen.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/fehlerbehebung/log-meldungen.md","filePath":"de/adapter/sourceanalytix/fehlerbehebung/log-meldungen.md","lastUpdated":null}'),s={name:"de/adapter/sourceanalytix/fehlerbehebung/log-meldungen.md"};function l(o,e,d,u,h,c){return n(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="log-meldungen-und-fehler-beim-einrichten" tabindex="-1">Log-Meldungen und Fehler beim Einrichten <a class="header-anchor" href="#log-meldungen-und-fehler-beim-einrichten" aria-label="Permalink to &quot;Log-Meldungen und Fehler beim Einrichten&quot;">​</a></h1><p><a id="error-unit-not-supported-no"></a></p><h2 id="fehler-unit-not-supported-no-unit-defined-–-wie-trage-ich-die-einheit-ein" tabindex="-1">Fehler &quot;unit not supported&quot; / &quot;No unit defined&quot; – wie trage ich die Einheit ein? <a class="header-anchor" href="#fehler-unit-not-supported-no-unit-defined-–-wie-trage-ich-die-einheit-ein" aria-label="Permalink to &quot;Fehler &quot;unit not supported&quot; / &quot;No unit defined&quot; – wie trage ich die Einheit ein?&quot;">​</a></h2><p><strong>Kurz:</strong> SourceAnalytix findet für den Datenpunkt keine Einheit, mit der es rechnen kann, und berechnet ihn nicht. Ab v0.7.0 steht die Quelle dann in den Instanz-Einstellungen im Tab „Probleme“ mit „Einheit fehlt oder wird nicht erkannt“. Klicke dort auf „Beheben“ und wähle die Einheit, in der das Gerät den Wert liefert.</p><p>So sieht die Meldung im Log aus:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>No unit defined for &lt;Datenpunkt&gt;, cannot execute calculations !</span></span>
<span class="line"><span>Please choose unit manually in state configuration</span></span>
<span class="line"><span>Cannot handle calculations for &lt;Datenpunkt&gt;, check log messages and adjust settings!</span></span></code></pre></div><p>Der Datenpunkt wird dann nicht berechnet, und SourceAnalytix legt für ihn keine States an. Die Meldung <code>Sorry unite type … not supported</code> stammt aus alten Versionen bis v0.4.2. Seit v0.4.7 heißt sie <code>No unit defined</code>.</p><h3 id="woher-die-meldung-kommt" tabindex="-1">Woher die Meldung kommt <a class="header-anchor" href="#woher-die-meldung-kommt" aria-label="Permalink to &quot;Woher die Meldung kommt&quot;">​</a></h3><p>SourceAnalytix nimmt die Einheit, die du bei der Quelle gewählt hast (ab v0.7.0 in der Detailansicht der Quelle unter „Einheit“, bis v0.6.x im Dialog am Datenpunkt unter „Wählen Sie Einheit“). Steht dort „Automatisch erkennen“, nimmt es die Einheit am Objekt des Datenpunkts. Die Meldung erscheint, wenn beides nicht klappt:</p><ul><li>Das Objekt hat <strong>keine Einheit</strong>. Das ist oft bei Datenpunkten aus Skripten oder bei selbst angelegten Datenpunkten so.</li><li>Die Einheit am Objekt ist <strong>nicht in der Liste</strong>, zum Beispiel <code>Watt</code> statt <code>W</code>, <code>m3</code> statt <code>m³</code> oder <code>m³/h</code>.</li><li>Die Größe wird <strong>gar nicht unterstützt</strong>, zum Beispiel Stück, Impulse, Betriebsstunden oder <code>%</code>. <strong>Ab v0.7.0</strong> gibt es für Stück und Impulse die Einheiten <code>piece</code> und <code>piece/min</code> (siehe <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Stück und Impulse</a>).</li></ul><p>Welche Einheiten es gibt, steht in der <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Referenz der Einheiten</a>.</p><h3 id="so-gehst-du-vor-ab-v0-7-0" tabindex="-1">So gehst du vor (ab v0.7.0) <a class="header-anchor" href="#so-gehst-du-vor-ab-v0-7-0" aria-label="Permalink to &quot;So gehst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne unter „Instanzen“ die Einstellungen der SourceAnalytix-Instanz und dort den Tab „Probleme“. Die Instanz muss laufen.</li><li>Suche die Zeile deiner Quelle mit „Einheit fehlt oder wird nicht erkannt“ und klicke auf „Beheben“.</li><li>Der Dialog „Einheit beheben“ zeigt, welche Einheit der Datenpunkt meldet. Wähle unter „Einheit“ die Einheit, in der das Gerät zählt. Liefert dein Gaszähler <code>m3</code>, wählst du <code>m³</code>. Liefert die Steckdose Watt, wählst du <code>W</code>.</li><li>Klicke auf „Übernehmen“. Die Einstellung wirkt sofort, ohne Neustart. Im Log steht danach <code>Enable SourceAnalytix for : &lt;Datenpunkt&gt;</code> ohne Fehlermeldung, und nach „Erneut prüfen“ ist die Zeile im Tab „Probleme“ verschwunden.</li></ol><p><img src="`+r+`" alt="Tab „Probleme“ mit geöffnetem Dialog „Einheit beheben“"></p><p>Dieselbe Auswahl findest du in der Detailansicht der Quelle unter „Einstellungen“, Feld „Einheit“. Eine neue Quelle legst du am besten mit „Quelle hinzufügen“ an: Der Assistent geht erst weiter, wenn eine Einheit gewählt ist.</p><p><strong>Bis v0.6.x:</strong> Öffne die SourceAnalytix-Einstellungen des Datenpunkts (<a href="./../erste-schritte/erster-zaehler#configure-sourceanalytix-datapoint">so findest du sie</a>), wähle unter „Wählen Sie Einheit“ die Einheit und speichere. Findet der Dialog keine passende Einheit, zeigt er „Keine passende Einheit erkannt. Bitte eine Einheit auswählen“ und speichert nicht.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Wähle die Einheit, die das Gerät <strong>liefert</strong>, nicht die, die du sehen willst. In welcher Einheit SourceAnalytix rechnet und anzeigt, legt die Preisdefinition fest. Wählst du <code>kWh</code>, obwohl das Gerät <code>Wh</code> liefert, sind alle Werte 1.000-mal zu groß.</p></div><p>Steht im Log stattdessen <code>reading incorrect after conversion contact DEV</code>, passt die Einheit des Datenpunkts nicht zur Einheit der Preisdefinition, zum Beispiel <code>kg</code> und <code>kWh</code>. Ab v0.6.2 meldet SourceAnalytix das schon beim Start: <code>Unit &lt;Einheit&gt; of &lt;Datenpunkt&gt; cannot be converted to unit &lt;Einheit&gt; of price definition &lt;Name&gt;</code> (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1278" target="_blank" rel="noreferrer">#1278</a>). Wähle dann eine Preisdefinition mit passender Einheit. Ab v0.7.0 steht die Quelle in diesem Fall im Tab „Probleme“ mit „Einheit passt nicht zum Preis“. Bis v0.6.1 erscheint dieselbe Meldung auch, wenn die Quelle Text statt einer Zahl liefert (siehe <a href="#source-delivers-text-instead-number">Quelle liefert Text statt Zahl</a>).</p><p><strong>Ab v0.6.2:</strong> SourceAnalytix erkennt am Objekt auch die Schreibweisen <code>m3</code>, <code>kwh</code> und ähnliche und rechnet mit <code>m³</code> bzw. <code>kWh</code> (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1264" target="_blank" rel="noreferrer">#1264</a>). Im Log steht dann <code>Unit &quot;m3&quot; of &lt;Datenpunkt&gt; is used as m³</code>. Auch der Einstellungsdialog nimmt diese Schreibweisen bei „Automatisch erkennen“ an (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1278" target="_blank" rel="noreferrer">#1278</a>). Ausgeschriebene Namen wie <code>Watt</code> oder <code>Liter</code> wählst du weiterhin von Hand aus.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Welche Einheiten werden unterstützt?</a> · <a href="./../anleitungen/quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Welche Einheit stelle ich am Datenpunkt ein?</a></p><p><a id="error-known-valueatdevicereset-known-cumulative"></a></p><h2 id="fehler-known-valueatdevicereset-known-cumulative-value" tabindex="-1">Fehler &quot;Known valueAtDeviceReset &gt; known cumulative value&quot; <a class="header-anchor" href="#fehler-known-valueatdevicereset-known-cumulative-value" aria-label="Permalink to &quot;Fehler &quot;Known valueAtDeviceReset &gt; known cumulative value&quot;&quot;">​</a></h2><p><strong>Kurz:</strong> Der gespeicherte Offset (<code>valueAtDeviceReset</code>) ist größer als der Gesamtstand (<code>cumulativeReading</code>). Ab v0.6.2 ist das nur noch eine Warnung: Die Quelle läuft weiter, und SourceAnalytix richtet den Offset mit dem nächsten Wert selbst aus. Prüfe danach den Gesamtstand und gleiche ihn bei Bedarf mit der Aktion „Zählerstand angleichen“ an deinen Zähler an. Bis v0.6.1 startet die Quelle bei diesem Fehler nicht.</p><p>Die Begriffe Gesamtstand, Gerätewert und Offset sind unter <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Die Begriffe</a> erklärt. Es gilt immer: Gesamtstand = Gerätewert + Offset.</p><h3 id="so-sieht-die-meldung-aus" tabindex="-1">So sieht die Meldung aus <a class="header-anchor" href="#so-sieht-die-meldung-aus" aria-label="Permalink to &quot;So sieht die Meldung aus&quot;">​</a></h3><p>Ab v0.6.2 steht beim Start eine Warnung im Log, mit dem nächsten Wert der Quelle folgt die zweite Zeile:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Known valueAtDeviceReset (&lt;Offset&gt;) of &lt;Datenpunkt&gt; is larger than the known cumulative value (&lt;Gesamtstand&gt;); the offset will be realigned with the next reading so the total continues from &lt;Gesamtstand&gt;</span></span>
<span class="line"><span>Realigned valueAtDeviceReset of &lt;Datenpunkt&gt; from &lt;alter Offset&gt; to &lt;neuer Offset&gt;: device value &lt;Gerätewert&gt;, total continues from &lt;Gesamtstand&gt;</span></span></code></pre></div><p>Bis v0.6.1 ist es ein Fehler, und die Quelle wird nicht gestartet:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Check settings for &lt;Datenpunkt&gt; ! Known valueAtDeviceReset : (&lt;Offset&gt;) &gt; known cumulative value (&lt;Gesamtstand&gt;) cannot proceed</span></span>
<span class="line"><span>Troubleshoot Data &lt;Datenpunkt&gt; custom Data : {…}</span></span>
<span class="line"><span>Cannot handle calculations for &lt;Datenpunkt&gt;, check log messages and adjust settings!</span></span></code></pre></div><h3 id="woher-die-meldung-kommt-1" tabindex="-1">Woher die Meldung kommt <a class="header-anchor" href="#woher-die-meldung-kommt-1" aria-label="Permalink to &quot;Woher die Meldung kommt&quot;">​</a></h3><p>Der Offset steht in den SourceAnalytix-Einstellungen des Datenpunkts, der Gesamtstand im State <code>sourceanalytix.0.&lt;Gerät&gt;.cumulativeReading</code>. Passen beide nicht mehr zusammen, kommt die Meldung. Typische Auslöser:</p><ul><li>Du hast nur <code>cumulativeReading</code> von Hand gesenkt oder auf 0 gesetzt, zum Beispiel nach einer alten Anleitung.</li><li>Der State <code>cumulativeReading</code> oder der ganze Ordner der Quelle wurde gelöscht. Ein fehlender Gesamtstand zählt als 0, der Offset in den Einstellungen bleibt.</li><li>Nach einem Zählertausch oder einem Restore stammen Gesamtstand und Einstellungen aus verschiedenen Zeitpunkten.</li></ul><p>Leistungsquellen (W) und andere Quellen, deren Gesamtstand SourceAnalytix selbst aufsummiert, haben keinen Offset. Für sie gibt es die Meldung nicht.</p><h3 id="so-gehst-du-vor-ab-v0-7-0-1" tabindex="-1">So gehst du vor (ab v0.7.0) <a class="header-anchor" href="#so-gehst-du-vor-ab-v0-7-0-1" aria-label="Permalink to &quot;So gehst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne unter „Instanzen“ die Einstellungen der SourceAnalytix-Instanz und im Tab „Übersicht“ deine Quelle.</li><li>Vergleiche den „Gesamtstand“ mit deinem Zähler. Stimmt er, musst du nichts tun. Den Offset richtet SourceAnalytix mit dem nächsten Wert selbst aus.</li><li>Stimmt er nicht, wähle bei „Aktionen“ den Eintrag „Zählerstand angleichen“, trage bei „Was zeigt dein Zähler jetzt?“ den abgelesenen Stand ein und klicke auf „Angleichen“. SourceAnalytix setzt Gesamtstand und Offset passend zueinander, sofort und ohne Neustart.</li></ol><p>Solange der nächste Wert noch nicht da ist, steht die Quelle auch im Tab „Probleme“ mit „Gesamtstand passt nicht zum Zähler“. Der Knopf „Angleichen“ in dieser Zeile öffnet dieselbe Aktion. Den aktuellen Offset zeigt die Detailansicht der Quelle unter „Für Experten“ als <code>valueAtDeviceReset</code>.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Die automatische Ausrichtung zählt vom gespeicherten Gesamtstand weiter, auch wenn dieser falsch ist. Wurde <code>cumulativeReading</code> auf 0 gesetzt oder gelöscht, beginnt der Gesamtstand also bei 0. Gleiche ihn dann mit „Zählerstand angleichen“ an deinen Zähler an.</p></div><p><strong>Bis v0.6.1:</strong> Aktualisiere auf v0.6.2 oder neuer (siehe <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">Wie aktualisiere ich SourceAnalytix?</a>). Geht das nicht, korrigierst du Gesamtstand und Offset bei gestoppter Instanz von Hand, wie unter <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a> im Teil „Bis v0.6.x“ beschrieben.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a> · <a href="./../anleitungen/zaehlerstaende-korrigieren#replaced-meter-device-avoid-negative">Zähler oder Gerät getauscht</a> · <a href="./falsche-werte-und-bekannte-fehler#after-update-restore-values-0">Nach Update oder Restore sind Werte 0</a></p><p><a id="error-no-cost-type-defined"></a></p><h2 id="fehler-no-cost-type-defined-–-preisdefinition-fehlt" tabindex="-1">Fehler &quot;No cost type defined&quot; – Preisdefinition fehlt <a class="header-anchor" href="#fehler-no-cost-type-defined-–-preisdefinition-fehlt" aria-label="Permalink to &quot;Fehler &quot;No cost type defined&quot; – Preisdefinition fehlt&quot;">​</a></h2><p><strong>Kurz:</strong> Jede Quelle braucht eine Preisdefinition, auch wenn du nur den Verbrauch willst. Ihre Einheit ist die Zieleinheit, in der SourceAnalytix rechnet. Ab v0.7.0 steht eine Quelle ohne gültige Preisdefinition im Tab „Probleme“. Mit „Preis wählen“ öffnest du die Quelle und wählst unter „Preisdefinition“ eine aus.</p><h3 id="so-sieht-die-meldung-aus-1" tabindex="-1">So sieht die Meldung aus <a class="header-anchor" href="#so-sieht-die-meldung-aus-1" aria-label="Permalink to &quot;So sieht die Meldung aus&quot;">​</a></h3><p>Ist bei der Quelle keine Preisdefinition gewählt:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>No cost type defined for &lt;Datenpunkt&gt;, please Select Type of calculation at state setting</span></span>
<span class="line"><span>Cannot handle calculations for &lt;Datenpunkt&gt;, check log messages and adjust settings!</span></span></code></pre></div><p>Ist eine Preisdefinition gewählt, die es nicht mehr gibt, zum Beispiel weil ihre „Kategorie“ umbenannt oder gelöscht wurde:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Selected Type &lt;Name&gt; does not exist in Price Definitions</span></span>
<span class="line"><span>Please choose proper type for state &lt;Datenpunkt&gt;</span></span>
<span class="line"><span>Or add price definition &lt;Name&gt; in adapter settings</span></span></code></pre></div><p>In beiden Fällen wird die Quelle nicht berechnet, und es entstehen keine States. Im Tab „Probleme“ heißen die Fälle „Keine Preisdefinition gewählt“ und „Preisdefinition gibt es nicht mehr“. Die alte Meldung <code>Error in case handling of cost type identification: undefined</code> gibt es in aktuellen Versionen nicht mehr.</p><h3 id="so-gehst-du-vor-ab-v0-7-0-2" tabindex="-1">So gehst du vor (ab v0.7.0) <a class="header-anchor" href="#so-gehst-du-vor-ab-v0-7-0-2" aria-label="Permalink to &quot;So gehst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Gibt es noch keine passende Preisdefinition, lege sie in den Instanz-Einstellungen im Tab „Preisdefinitionen“ an. Wichtig ist die „Einheit“: Sie muss zur Quelle passen, zum Beispiel <code>kWh</code> für einen Stromzähler oder eine Leistung in W. Speichern startet den Adapter neu.</li><li>Öffne den Tab „Probleme“ und klicke in der Zeile der Quelle auf „Preis wählen“. Die Detailansicht der Quelle öffnet sich.</li><li>Wähle unter „Einstellungen“ bei „Preisdefinition“ eine Kategorie. Die Liste zeigt die Einheit in Klammern, zum Beispiel <code>Strom (kWh)</code>.</li><li>Klicke auf „Übernehmen“. Die Quelle startet sofort, ohne Neustart.</li></ol><p>Passt die Einheit der Preisdefinition nicht zur Quelle, meldet der Tab „Probleme“ danach „Einheit passt nicht zum Preis“ (siehe <a href="#error-unit-not-supported-no">Fehler „unit not supported“ / „No unit defined“</a>). Der Assistent „Quelle hinzufügen“ bietet nur Preisdefinitionen mit passender Einheit an und geht ohne Auswahl nicht weiter.</p><p><strong>Bis v0.6.x:</strong> Wähle im Dialog am Datenpunkt bei „Preisdefinition auswählen“ eine Kategorie und speichere (<a href="./../erste-schritte/erster-zaehler#configure-sourceanalytix-datapoint">so findest du den Dialog</a>). Seit v0.6.0 lässt sich der Dialog ohne Preisdefinition nicht mehr speichern.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#price-definition-structured-categories-base">Wie ist eine Preisdefinition aufgebaut?</a> · <a href="./../anleitungen/preise-und-kosten#assign-prices-create-custom-tariffs">Preise zuordnen und eigene Tarife anlegen</a> · <a href="./falsche-werte-und-bekannte-fehler#costs-stay-0-not-calculated">Kosten bleiben 0</a></p><p><a id="messages-initialization-failed-cannot-handle"></a></p><h2 id="meldungen-initialization-failed-cannot-handle-calculations-reading-incorrect" tabindex="-1">Meldungen &quot;Initialization failed&quot; / &quot;Cannot handle calculations&quot; / &quot;reading incorrect&quot; <a class="header-anchor" href="#meldungen-initialization-failed-cannot-handle-calculations-reading-incorrect" aria-label="Permalink to &quot;Meldungen &quot;Initialization failed&quot; / &quot;Cannot handle calculations&quot; / &quot;reading incorrect&quot;&quot;">​</a></h2><p><strong>Kurz:</strong> Das sind Sammelmeldungen. Sie sagen nur, dass SourceAnalytix eine Quelle nicht gestartet hat oder einen Wert nicht rechnen konnte. Die Ursache steht in den Log-Zeilen direkt davor. Ab v0.7.0 zeigt der Tab „Probleme“ in den Instanz-Einstellungen die Ursache mit einem Vorschlag zur Lösung.</p><h3 id="meldungen-beim-start-und-beim-aktivieren" tabindex="-1">Meldungen beim Start und beim Aktivieren <a class="header-anchor" href="#meldungen-beim-start-und-beim-aktivieren" aria-label="Permalink to &quot;Meldungen beim Start und beim Aktivieren&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Meldung</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>Initialization of &lt;Datenpunkt&gt; successfully</code></td><td>Die Quelle läuft.</td></tr><tr><td><code>Initialization of &lt;Datenpunkt&gt; failed, check warn messages !</code></td><td>Die Quelle wurde nicht gestartet. Der Grund steht davor.</td></tr><tr><td><code>Cannot handle calculations for &lt;Datenpunkt&gt;, check log messages and adjust settings!</code></td><td>Dasselbe für eine einzelne Quelle, direkt nach dem Grund.</td></tr><tr><td><code>Cannot handle calculations for &lt;n&gt; of &lt;m&gt; enabled states, check error messages</code></td><td>Zusammenfassung am Ende des Starts: n von m Quellen laufen nicht.</td></tr><tr><td><code>Partially activated SourceAnalytix for &lt;k&gt; of &lt;m&gt; states, check error messages!</code></td><td>Die übrigen Quellen laufen.</td></tr><tr><td><code>[Cannot enable SourceAnalytix for &lt;Datenpunkt&gt;, check settings and error messages</code></td><td>Eine Quelle, die du im laufenden Betrieb aktiviert oder geändert hast, konnte nicht starten.</td></tr><tr><td><code>Cannot handle initialisation for &lt;Datenpunkt&gt;</code></td><td>Folgemeldung: Für die Quelle liegen keine geprüften Einstellungen vor. Auch hier steht der Grund davor.</td></tr></tbody></table><p>Häufige Gründe in den Zeilen davor:</p><ul><li><code>No unit defined for …</code>: siehe <a href="#error-unit-not-supported-no">Fehler „unit not supported“ / „No unit defined“</a>.</li><li><code>No cost type defined for …</code> oder <code>Selected Type … does not exist in Price Definitions</code>: siehe <a href="#error-no-cost-type-defined">Fehler „No cost type defined“</a>.</li><li><code>Unit … of … cannot be converted to unit … of price definition …</code>: Einheit und Preisdefinition passen nicht zusammen, siehe ebenfalls <a href="#error-unit-not-supported-no">Fehler „unit not supported“</a>.</li><li><code>Cannot use output ID … no existing output tree to keep</code>: Die gewünschte technische ID ist ungültig oder schon vergeben, siehe <a href="./../referenz/einstellungen#name-datapoint-alias-output-id">Name, Alias und Output-ID</a>.</li><li>Bis v0.6.1 auch <code>Check settings for … Known valueAtDeviceReset …</code>: siehe <a href="#error-known-valueatdevicereset-known-cumulative">Fehler „Known valueAtDeviceReset &gt; known cumulative value“</a>.</li></ul><p>Sobald du die Ursache in den Einstellungen behebst und übernimmst, startet SourceAnalytix die Quelle ohne Neustart. Im Log steht dann <code>Enable SourceAnalytix for : &lt;Datenpunkt&gt;</code> ohne Fehler danach.</p><h3 id="meldung-„reading-incorrect-after-conversion" tabindex="-1">Meldung „reading incorrect after conversion“ <a class="header-anchor" href="#meldung-„reading-incorrect-after-conversion" aria-label="Permalink to &quot;Meldung „reading incorrect after conversion“&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[calculationHandler] reading incorrect after conversion contact DEV and provide these info | Reading : null | start reading {…} | stateDetails {…}</span></span></code></pre></div><p>Bis v0.6.1 kommt sie bei jedem Wert, wenn die Quelle keine Zahl liefert (zum Beispiel <code>null</code> oder Text wie <code>&quot;12,5&quot;</code>) oder wenn die Einheit der Quelle nicht zur Preisdefinition passt, zum Beispiel <code>kg</code> und <code>kWh</code>. Die Quelle läuft, rechnet aber nichts. Schau im Verlauf des Quell-Datenpunkts nach, was zur Zeit der Meldung ankam, und prüfe die Einheit.</p><p><strong>Ab v0.6.2</strong> fängt SourceAnalytix beide Ursachen vorher ab: Zahlen in Text liest es selbst, einen Wert ohne Zahl überspringt es mit der Warnung <code>Value &lt;Wert&gt; of &lt;Datenpunkt&gt; is not a number, reading ignored</code> (siehe <a href="#source-delivers-text-instead-number">Quelle liefert Text statt Zahl</a>). Unpassende Einheiten lehnt es schon beim Start ab. Erscheint die Meldung trotzdem, melde sie mit der ganzen Log-Zeile als Issue im Adapter-Repository.</p><p><strong>Siehe auch:</strong> <a href="#datapoint-enabled-but-no-folders">Datenpunkt aktiviert, aber es entstehen keine Ordner</a> · <a href="#high-cpu-memory-use-too">Hohe CPU-Last und zu viel Log-Ausgabe</a></p><p><a id="source-delivers-text-instead-number"></a></p><h2 id="quelle-liefert-text-statt-zahl-string-statt-number-dezimalpunkt" tabindex="-1">Quelle liefert Text statt Zahl (string statt number, Dezimalpunkt) <a class="header-anchor" href="#quelle-liefert-text-statt-zahl-string-statt-number-dezimalpunkt" aria-label="Permalink to &quot;Quelle liefert Text statt Zahl (string statt number, Dezimalpunkt)&quot;">​</a></h2><p><strong>Kurz:</strong> Ab v0.6.2 liest SourceAnalytix Zahlen aus Text selbst, mit Komma oder Punkt, zum Beispiel <code>&quot;12,5&quot;</code> oder <code>&quot;.14&quot;</code>. Text mit Einheit oder Tausenderpunkt, zum Beispiel <code>&quot;12,5 kWh&quot;</code> oder <code>&quot;1.234,5&quot;</code>, kann es nicht lesen und überspringt den Wert mit einer Warnung. Am sichersten ist ein Quell-Datenpunkt vom Typ Zahl.</p><h3 id="so-erkennst-du-es" tabindex="-1">So erkennst du es <a class="header-anchor" href="#so-erkennst-du-es" aria-label="Permalink to &quot;So erkennst du es&quot;">​</a></h3><ul><li><strong>Ab v0.7.0</strong> steht die Quelle im Tab „Probleme“ mit dem Hinweis „Datenpunkt liefert Text statt einer Zahl“, solange der letzte Wert Text ist. Der Knopf „Anleitung“ führt hierher.</li><li><strong>Ab v0.6.2</strong> steht bei einem Text ohne lesbare Zahl im Log <code>Value &quot;&lt;Wert&gt;&quot; of &lt;Datenpunkt&gt; is not a number, reading ignored</code>. Der Wert zählt nicht, der nächste lesbare Wert schon.</li><li><strong>Bis v0.6.1</strong> rechnet SourceAnalytix mit keinem Text-Wert. Bei Zählerständen steht bei jedem Wert <code>reading incorrect after conversion contact DEV … Reading : null</code> im Log, die Quelle bleibt ohne Werte.</li></ul><p><strong>Ab v0.7.0</strong> liest SourceAnalytix auch bei Leistungsquellen (W) Text mit Komma oder Punkt, zum Beispiel <code>&quot;1,5&quot;</code>, so wie bei Zählerständen. Ist der Text keine Zahl, steht <code>Value &quot;&lt;Wert&gt;&quot; of &lt;Datenpunkt&gt; is not a number, reading ignored</code> im Log, und der Wert zählt nicht (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1288" target="_blank" rel="noreferrer">#1288</a>).</p><p><strong>Bis v0.6.x</strong> wandelt SourceAnalytix Text bei Leistungsquellen nur mit Dezimalpunkt um (<code>&quot;12.5&quot;</code>). Mit Komma steht bei jedem Wert <code>[wattToWattHour] Invalid power reading interval for &lt;Datenpunkt&gt;, using current reading as new baseline</code> im Log, und es entsteht kein Verbrauch.</p><h3 id="so-stellst-du-auf-eine-zahl-um" tabindex="-1">So stellst du auf eine Zahl um <a class="header-anchor" href="#so-stellst-du-auf-eine-zahl-um" aria-label="Permalink to &quot;So stellst du auf eine Zahl um&quot;">​</a></h3><ol><li>Prüfe zuerst, ob der Quell-Adapter eine Einstellung für Zahlen hat oder einen anderen Datenpunkt mit dem Zählerstand als Zahl anbietet. Den nimmst du.</li><li>Sonst legst du einen eigenen Datenpunkt vom Typ „Zahl“ an, zum Beispiel einen Alias vom Typ Zahl, dessen Lesefunktion den Text umwandelt, oder ein Skript, das den Text mit <code>parseFloat</code> umwandelt und in den neuen Datenpunkt schreibt. Ersetze dabei vorher das Komma durch einen Punkt.</li><li>Gib dem neuen Datenpunkt die Einheit, in der das Gerät zählt, zum Beispiel <code>kWh</code>.</li><li>Richte den neuen Datenpunkt mit „Quelle hinzufügen“ als Quelle ein.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Der neue Datenpunkt ist für SourceAnalytix eine neue Quelle mit einem eigenen Ordner. Die Werte der alten Quelle bleiben in ihrem Ordner stehen. Den Zählerstand übernimmst du mit <a href="./../erste-schritte/erster-zaehler#start-values-unit">Startwerten</a> oder mit „Zählerstand angleichen“.</p></div><p><strong>Siehe auch:</strong> <a href="./../anleitungen/quellen-und-einheiten#use-script-datapoints-unreliable-sources">Skript-Datenpunkte und unzuverlässige Quellen</a> · <a href="#messages-initialization-failed-cannot-handle">Meldung „reading incorrect after conversion“</a></p><p><a id="datapoint-enabled-but-no-folders"></a></p><h2 id="datenpunkt-aktiviert-aber-es-entstehen-keine-ordner-oder-states" tabindex="-1">Datenpunkt aktiviert, aber es entstehen keine Ordner oder States <a class="header-anchor" href="#datenpunkt-aktiviert-aber-es-entstehen-keine-ordner-oder-states" aria-label="Permalink to &quot;Datenpunkt aktiviert, aber es entstehen keine Ordner oder States&quot;">​</a></h2><p><strong>Kurz:</strong> Fast immer hat SourceAnalytix die Quelle abgelehnt, meist wegen einer fehlenden Preisdefinition oder Einheit. Ab v0.7.0 siehst du das in den Instanz-Einstellungen: Im Tab „Übersicht“ hat die Quelle den Status „Problem“, im Tab „Probleme“ stehen der Grund und ein Knopf zur Lösung.</p><h3 id="checkliste-ab-v0-7-0" tabindex="-1">Checkliste (ab v0.7.0) <a class="header-anchor" href="#checkliste-ab-v0-7-0" aria-label="Permalink to &quot;Checkliste (ab v0.7.0)&quot;">​</a></h3><ol><li><strong>Läuft die Instanz?</strong> Ohne laufende Instanz rechnet SourceAnalytix nicht, und die Übersicht zeigt „Die Übersicht braucht eine laufende Instanz.“</li><li><strong>Steht die Quelle im Tab „Übersicht“?</strong> Wenn nicht, ist der Datenpunkt nicht für diese Instanz eingerichtet, zum Beispiel für <code>sourceanalytix.1</code> statt <code>sourceanalytix.0</code>. Richte ihn mit „Quelle hinzufügen“ ein. Der Assistent prüft Einheit und Preis, bevor er speichert.</li><li><strong>Welchen Status hat sie?</strong> „Deaktiviert“: Öffne die Quelle und wähle bei „Aktionen“ den Eintrag „Aktivieren“. „Problem“ oder „Hinweis“: weiter mit Schritt 4.</li><li><strong>Was steht im Tab „Probleme“?</strong> „Keine Preisdefinition gewählt“, „Preisdefinition gibt es nicht mehr“, „Einheit fehlt oder wird nicht erkannt“, „Einheit passt nicht zum Preis“ oder „Datenpunkt existiert nicht mehr“. Der Knopf in der Zeile behebt das Problem oder öffnet die passende Stelle.</li><li><strong>Was steht im Log?</strong> Nach <code>Enable SourceAnalytix for : &lt;Datenpunkt&gt;</code> folgt bei einem Fehler der Grund, siehe <a href="#messages-initialization-failed-cannot-handle">Meldungen „Initialization failed“ / „Cannot handle calculations“</a>.</li><li><strong>Ist „Verbrauch“ angehakt?</strong> Ohne den Haken bei „Verbrauch“ in den Einstellungen der Quelle entstehen keine Verbrauchswerte für Tag, Woche, Monat, Quartal und Jahr.</li></ol><p>Läuft die Quelle, legt SourceAnalytix sofort den Ordner <code>sourceanalytix.0.&lt;Gerät&gt;</code> an. Die ersten Werte erscheinen mit dem nächsten Wert des Datenpunkts. Siehst du den Ordner im Reiter „Objekte“ trotzdem nicht, lade die Ansicht neu und prüfe, ob ein Filter der Objektliste aktiv ist.</p><p><strong>Ab v0.7.0:</strong> Hast du die Quelle im Reiter „Objekte“ am Datenpunkt über „aktiviert“ eingeschaltet, ist noch keine Preisdefinition gewählt. Die Quelle steht dann im Tab „Probleme“ mit „Keine Preisdefinition gewählt“. Wähle die Preisdefinition in ihrer Detailansicht und klicke auf „⚡ Übernehmen“ (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1286" target="_blank" rel="noreferrer">#1286</a>).</p><p><strong>Bis v0.6.x:</strong> Prüfe dieselben Punkte im Dialog am Datenpunkt und im Log. Seit v0.6.0 speichert der Dialog nicht ohne Preisdefinition und Einheit. Alte Hinweise, man müsse einen Startwert eintragen, gelten nicht mehr: Leere Startwerte setzt SourceAnalytix bei der ersten Aktivierung selbst.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erster-zaehler#configure-sourceanalytix-datapoint">Wo konfiguriere ich SourceAnalytix für einen Datenpunkt?</a> · <a href="./../erste-schritte/erster-zaehler#values-consumption-today-yesterday">Wo finde ich meine Werte?</a></p><p><a id="high-cpu-memory-use-too"></a></p><h2 id="hohe-cpu-speicherlast-und-zu-viel-log-ausgabe" tabindex="-1">Hohe CPU-/Speicherlast und zu viel Log-Ausgabe <a class="header-anchor" href="#hohe-cpu-speicherlast-und-zu-viel-log-ausgabe" aria-label="Permalink to &quot;Hohe CPU-/Speicherlast und zu viel Log-Ausgabe&quot;">​</a></h2><p><strong>Kurz:</strong> SourceAnalytix rechnet bei jedem neuen Wert jeder Quelle. Viel Last entsteht durch Quellen, die sehr oft senden. Bis v0.6.1 kam eine Dauerlast durch ständiges Neu-Initialisieren dazu, die ab v0.6.2 behoben ist. Für weniger Log-Ausgabe stellst du die Instanz auf die Log-Stufe „warn“.</p><h3 id="last-senken" tabindex="-1">Last senken <a class="header-anchor" href="#last-senken" aria-label="Permalink to &quot;Last senken&quot;">​</a></h3><ul><li><strong>Aktualisieren:</strong> Bis v0.6.1 baut SourceAnalytix bei jeder Änderung am Objekt einer aktiven Quelle die Quelle neu auf, auch wenn sich nichts geändert hat. <strong>Ab v0.6.2</strong> übergeht es solche Änderungen und schreibt Objekte nur, wenn sich ihre Definition ändert (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1233" target="_blank" rel="noreferrer">#1233</a>).</li><li><strong>Seltener senden:</strong> Jede Aktualisierung des Quell-Datenpunkts löst eine Berechnung aus. Sendet ein Gerät jede Sekunde, stelle im Quell-Adapter ein längeres Intervall ein, wenn das geht.</li><li><strong>Zählerstand statt Leistung:</strong> Liefert dein Gerät einen Zählerstand (kWh), nimm ihn statt der Leistung (W). Siehe <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Zähler (kWh) oder Leistung (W)?</a>.</li><li><strong>Nur nötige Quellen:</strong> Quellen, die du nicht brauchst, schaltest du ab v0.7.0 bei der Quelle mit „Deaktivieren“ ab. Die Daten bleiben erhalten.</li></ul><h3 id="weniger-log-ausgabe" tabindex="-1">Weniger Log-Ausgabe <a class="header-anchor" href="#weniger-log-ausgabe" aria-label="Permalink to &quot;Weniger Log-Ausgabe&quot;">​</a></h3><p>Eine neue Instanz startet mit der Log-Stufe „info“. Dann schreibt SourceAnalytix beim Start mehrere Zeilen je Quelle. Für den Dauerbetrieb empfiehlt sich „warn“: Warnungen und Fehler siehst du weiter. Die Log-Stufe stellst du im Reiter „Instanzen“ bei der SourceAnalytix-Instanz ein (im Expertenmodus).</p><p><strong>Bis v0.6.1</strong> schreibt eine Quelle mit ausgeschalteter Reset-Erkennung bei jedem fallenden Wert <code>Cumulative reading for … decreased while reset detection is disabled</code> auf Stufe Info. <strong>Ab v0.6.2</strong> steht die Meldung nur noch im Debug-Log (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1262" target="_blank" rel="noreferrer">#1262</a>).</p><p>Füllt ein anderer Adapter das Log, zum Beispiel ein History-Adapter, hilft dessen Log-Stufe, nicht die von SourceAnalytix.</p><p><strong>Siehe auch:</strong> <a href="#object-limit-warning-5000">Warnung zum Objektlimit</a> · <a href="./falsche-werte-und-bekannte-fehler#known-bugs-older-versions-please">Bekannte Fehler älterer Versionen</a></p><p><a id="installation-admin-display-problems"></a></p><h2 id="probleme-bei-installation-und-admin-anzeige" tabindex="-1">Probleme bei Installation und Admin-Anzeige <a class="header-anchor" href="#probleme-bei-installation-und-admin-anzeige" aria-label="Permalink to &quot;Probleme bei Installation und Admin-Anzeige&quot;">​</a></h2><p><strong>Kurz:</strong> Installiere SourceAnalytix aus dem Repository „latest“ (Beta), nicht direkt von GitHub. Ab v0.7.0 braucht es Admin 8.0.0 oder neuer, js-controller 6.0.11 und Node.js 22. Fehlt nach der Installation etwas in Admin, lade die Adapterdateien in der Konsole mit <code>iobroker upload sourceanalytix</code> neu hoch.</p><p>Wie die Installation geht, steht unter <a href="./../erste-schritte/installation#install-sourceanalytix-create-instance">Installation und Instanz anlegen</a>.</p><h3 id="installation-von-github-bricht-mit-404-oder-422-ab" tabindex="-1">Installation von GitHub bricht mit 404 oder 422 ab <a class="header-anchor" href="#installation-von-github-bricht-mit-404-oder-422-ab" aria-label="Permalink to &quot;Installation von GitHub bricht mit 404 oder 422 ab&quot;">​</a></h3><p>Das ist ein Problem der ioBroker-Installation, nicht von SourceAnalytix. In den gemeldeten Fällen half ein Update des js-controllers. Einfacher ist die Installation aus dem Repository „latest“.</p><h3 id="sourceanalytix-oder-seine-einstellungen-fehlen-in-admin" tabindex="-1">SourceAnalytix oder seine Einstellungen fehlen in Admin <a class="header-anchor" href="#sourceanalytix-oder-seine-einstellungen-fehlen-in-admin" aria-label="Permalink to &quot;SourceAnalytix oder seine Einstellungen fehlen in Admin&quot;">​</a></h3><ul><li><strong>Kein Eintrag unter „Instanzen“:</strong> Nach der Installation musst du eine Instanz anlegen.</li><li><strong><code>Cannot load jsonConfig of sourceanalytix: Not exists</code> oder <code>index_m.html not found</code>:</strong> Admin findet die Dateien der Einstellungsseite nicht. Führe <code>iobroker upload sourceanalytix</code> aus und lade die Admin-Seite neu. Bei Versionen vor v0.4.9 fehlte diese Seite ganz, dann hilft nur ein Update.</li><li><strong>Tabs „Übersicht“ und „Probleme“ leer (ab v0.7.0):</strong> Steht dort „Die Übersicht braucht eine laufende Instanz.“ oder „Quellen konnten nicht geladen werden“, starte die Instanz und klicke auf „Erneut versuchen“. Ist die Instanz gestoppt, sind die Aktionen gesperrt. Einstellungen kannst du weiter ändern und speichern.</li></ul><h3 id="„nicht-gepflegt-und-unterschiedlich-große-symbole" tabindex="-1">„Nicht gepflegt“ und unterschiedlich große Symbole <a class="header-anchor" href="#„nicht-gepflegt-und-unterschiedlich-große-symbole" aria-label="Permalink to &quot;„Nicht gepflegt“ und unterschiedlich große Symbole&quot;">​</a></h3><p>Das Kennzeichen „nicht gepflegt“ hängt am Repository, aus dem du installiert hast. Bei einer Installation von GitHub fehlen diese Angaben. Unterschiedlich große Ordner-Symbole sind ein Darstellungseffekt von Admin im Browser am Handy. Beides ändert nichts an der Funktion von SourceAnalytix.</p><h3 id="multihost-„admin-not-found" tabindex="-1">Multihost: „admin not found“ <a class="header-anchor" href="#multihost-„admin-not-found" aria-label="Permalink to &quot;Multihost: „admin not found“&quot;">​</a></h3><p>SourceAnalytix setzt Admin voraus, ab v0.7.0 in Version 8.0.0 oder neuer. Meldet ein Host beim Start oder bei der Installation „admin not found“, installiere oder aktualisiere Admin. Im gemeldeten Fall fehlte Admin auf dem Host, auf dem die Instanz laufen sollte.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/installation#requirements-sourceanalytix-have-node-js">Was brauche ich für SourceAnalytix?</a> · <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">Wie aktualisiere ich SourceAnalytix?</a></p><p><a id="midnight-crash-rollover-wrong-time"></a></p><h2 id="mitternacht-absturz-oder-tageswechsel-zur-falschen-zeit" tabindex="-1">Mitternacht: Absturz oder Tageswechsel zur falschen Zeit <a class="header-anchor" href="#mitternacht-absturz-oder-tageswechsel-zur-falschen-zeit" aria-label="Permalink to &quot;Mitternacht: Absturz oder Tageswechsel zur falschen Zeit&quot;">​</a></h2><p><strong>Kurz:</strong> Der Periodenwechsel läuft um 0:00 Uhr nach der Systemzeit des Rechners oder Containers, auf dem ioBroker läuft. Ein Absturz mit <code>ENOENT</code> um Mitternacht kommt vom js-controller, nicht von SourceAnalytix. Einen verpassten Wechsel holt SourceAnalytix selbst nach. Ab v0.7.0 holst du ihn auch mit „Nachholen“ im Tab „Probleme“ nach.</p><h3 id="absturz-mit-enoent-um-mitternacht" tabindex="-1">Absturz mit ENOENT um Mitternacht <a class="header-anchor" href="#absturz-mit-enoent-um-mitternacht" aria-label="Permalink to &quot;Absturz mit ENOENT um Mitternacht&quot;">​</a></h3><p>Um Mitternacht wechselt der js-controller die Log-Datei. Fehlt die Datei dabei, kann ein Adapter mit <code>ENOENT</code> abstürzen. Das lässt sich in SourceAnalytix nicht verhindern. Wichtig ist nur, dass der verpasste Wechsel nachgeholt wird.</p><h3 id="so-holt-sourceanalytix-einen-wechsel-nach" tabindex="-1">So holt SourceAnalytix einen Wechsel nach <a class="header-anchor" href="#so-holt-sourceanalytix-einen-wechsel-nach" aria-label="Permalink to &quot;So holt SourceAnalytix einen Wechsel nach&quot;">​</a></h3><ul><li>Beim Start prüft SourceAnalytix jede Quelle und holt einen verpassten Wechsel sofort nach.</li><li>Läuft der Adapter, prüft er zusätzlich jede Stunde, ob ein Wechsel fehlt.</li><li><strong>Ab v0.7.0</strong> steht ein verpasster Wechsel im Tab „Probleme“ als „Periodenwechsel verpasst“. Der Knopf „Nachholen“ holt ihn für diese Quelle nach. Dasselbe macht die Aktion „Perioden nachholen“ bei der Quelle.</li><li>In allen Versionen ab v0.5.5 geht es auch über den Knopf-State <code>sourceanalytix.0.info.recoverPeriods</code>.</li></ul><p>Im Log steht dann <code>Processing calendar rollover for &lt;Datenpunkt&gt;: {…}</code>. Mehr dazu unter <a href="./../anleitungen/betrieb-und-wartung#iobroker-was-down-midnight-recover">ioBroker war über Mitternacht aus</a>.</p><p><strong>Ab v0.6.2:</strong> War ioBroker über Mitternacht aus, verteilt SourceAnalytix den Verbrauch der Lücke nach der Zeit auf beide Tage. Bis v0.6.1 landete alles im neuen Tag (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1260" target="_blank" rel="noreferrer">#1260</a>).</p><h3 id="der-tageswechsel-kommt-zur-falschen-uhrzeit" tabindex="-1">Der Tageswechsel kommt zur falschen Uhrzeit <a class="header-anchor" href="#der-tageswechsel-kommt-zur-falschen-uhrzeit" aria-label="Permalink to &quot;Der Tageswechsel kommt zur falschen Uhrzeit&quot;">​</a></h3><p>SourceAnalytix hat keine eigene Zeitzone. Der Wechsel folgt der Zeitzone des Prozesses, in dem ioBroker läuft. Steht ein Docker-Container zum Beispiel auf UTC, wechselt der Tag in Deutschland um 1:00 oder 2:00 Uhr. Stelle dann die Zeitzone des Rechners oder Containers richtig ein, bei Docker etwa mit der Umgebungsvariable <code>TZ=Europe/Berlin</code>, und starte den Container neu.</p><p><strong>Siehe auch:</strong> <a href="./../hintergrund/perioden-und-zeit#values-updated-live-midnight">Werden die Werte live aktualisiert, was passiert um Mitternacht?</a> · <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Vorperioden (previous-States)</a></p><p><a id="object-limit-warning-5000"></a></p><h2 id="warnung-zum-objektlimit-5000" tabindex="-1">Warnung zum Objektlimit (5000) <a class="header-anchor" href="#warnung-zum-objektlimit-5000" aria-label="Permalink to &quot;Warnung zum Objektlimit (5000)&quot;">​</a></h2><p><strong>Kurz:</strong> Die Warnung kommt vom js-controller, nicht von SourceAnalytix. Der Adapter selbst kennt kein Objektlimit. Jede aktive Quelle legt einen eigenen Ordner mit vielen States an. Prüfe zuerst, welche Optionen und Quellen du brauchst, und hebe das Limit nur an, wenn die Zahl gewollt ist.</p><h3 id="weniger-objekte" tabindex="-1">Weniger Objekte <a class="header-anchor" href="#weniger-objekte" aria-label="Permalink to &quot;Weniger Objekte&quot;">​</a></h3><ul><li>In den Instanz-Einstellungen unter „Haupteinstellungen“ legen die Bereiche „Jahresstatistik“ („Wochen“, „Monate“, „Quartale“) und „Laufendes Jahr“ („Wochentag“, „Wochen“, „Monate“, „Quartale“, „Vorheriger Zeitraum“) fest, welche States jede Quelle bekommt. Schaltest du eine Option ab, entfernt SourceAnalytix die zugehörigen States.</li><li>Quellen, die du nicht mehr brauchst, entfernst du ab v0.7.0 mit der Aktion „Daten löschen“ samt Ordner und allen Jahren.</li><li>Alte Jahres- und Wochenordner kannst du gefahrlos löschen.</li></ul><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>„Daten löschen“ entfernt den Ordner der Quelle mit allen Werten und Jahren endgültig. Willst du nur pausieren, nimm „Deaktivieren“.</p></div><h3 id="limit-anheben" tabindex="-1">Limit anheben <a class="header-anchor" href="#limit-anheben" aria-label="Permalink to &quot;Limit anheben&quot;">​</a></h3><p>Das Limit gehört zum js-controller. Im gemeldeten Fall ließ es sich im Expertenmodus am Objekt der Instanz (<code>system.adapter.sourceanalytix.0</code>) anheben.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#instance-settings-exist-periods-decimals">Welche Einstellungen hat die Instanz?</a> · <a href="./../anleitungen/betrieb-und-wartung#disable-datapoint-remove-sources-states">Quelle deaktivieren oder entfernen</a></p><p><a id="source-adapter-history-shows-0"></a></p><h2 id="quell-adapter-oder-history-zeigt-0-oder-alte-werte" tabindex="-1">Quell-Adapter oder History zeigt 0 oder alte Werte <a class="header-anchor" href="#quell-adapter-oder-history-zeigt-0-oder-alte-werte" aria-label="Permalink to &quot;Quell-Adapter oder History zeigt 0 oder alte Werte&quot;">​</a></h2><p><strong>Kurz:</strong> SourceAnalytix liest nur den Datenpunkt, den du als Quelle eingerichtet hast, und schreibt nie in dessen Wert. Zeigt SourceAnalytix 0 oder alte Werte, kommt am Quell-Datenpunkt meist nichts mehr an. Nullen im Verlauf des Quell-Datenpunkts stammen vom Quell-Adapter oder von einem Skript.</p><h3 id="der-quell-adapter-hat-seine-datenpunkte-umbenannt" tabindex="-1">Der Quell-Adapter hat seine Datenpunkte umbenannt <a class="header-anchor" href="#der-quell-adapter-hat-seine-datenpunkte-umbenannt" aria-label="Permalink to &quot;Der Quell-Adapter hat seine Datenpunkte umbenannt&quot;">​</a></h3><p>Benennt ein Adapter nach einem Update seine Datenpunkte um, kommen die Werte in neuen Datenpunkten an. SourceAnalytix hört weiter auf den alten, und seine Werte bleiben stehen.</p><ol><li>Öffne in den Instanz-Einstellungen die Quelle und prüfe „Letzte Aktualisierung“.</li><li>Ist der alte Datenpunkt gelöscht, steht die Quelle ab v0.7.0 im Tab „Probleme“ mit „Datenpunkt existiert nicht mehr“. Der Knopf „Deaktivieren“ hält die Quelle an, die Daten bleiben erhalten.</li><li>Richte den neuen Datenpunkt mit „Quelle hinzufügen“ als neue Quelle ein und übernimm den Zählerstand mit „Zählerstand angleichen“.</li><li>Passe Verknüpfungen in VIS oder Skripten auf den neuen Ordner an. Der alte Ordner bleibt als Archiv stehen.</li></ol><p>Die Aktion „Datenpunkt wechseln“, die die Daten zum neuen Datenpunkt mitnimmt, ist geplant (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1271" target="_blank" rel="noreferrer">#1271</a>).</p><h3 id="nullen-im-verlauf-des-quell-datenpunkts" tabindex="-1">Nullen im Verlauf des Quell-Datenpunkts <a class="header-anchor" href="#nullen-im-verlauf-des-quell-datenpunkts" aria-label="Permalink to &quot;Nullen im Verlauf des Quell-Datenpunkts&quot;">​</a></h3><p>SourceAnalytix schreibt Werte nur in seinen eigenen Ordner <code>sourceanalytix.0.&lt;Gerät&gt;</code>. Am Objekt des Quell-Datenpunkts ändert es nur seine eigenen Einstellungen, zum Beispiel den Offset, nicht den Wert. Eine 0 im Verlauf des Quell-Datenpunkts schreibt also ein anderer Adapter oder ein Skript.</p><p><strong>Siehe auch:</strong> <a href="#datapoint-enabled-but-no-folders">Datenpunkt aktiviert, aber es entstehen keine Ordner</a> · <a href="./../anleitungen/betrieb-und-wartung#disable-datapoint-remove-sources-states">Quelle deaktivieren oder entfernen</a></p>`,140)])])}const p=t(s,[["render",l]]);export{m as __pageData,p as default};
